_KINDS = ('index', 'stock', 'industry', 'concept')
_DIRECTIONS = ('up', 'down')
_SEVERITIES = ('high', 'medium', 'low')
_STATUSES = ('watching', 'active', 'confirmed', 'missed')


def _code_ok(kind, code):
    """与 detsig_target_code_format 同口径（SQLite LIKE 不分大小写，这里也不分）。"""
    code = code or ''
    if kind == 'index':
        return len(code) == 8 and code[:2].lower() in ('sh', 'sz', 'bj')
    if kind == 'stock':
        return len(code) == 6
    return code != ''


def clean_violations(apps, schema_editor):
    """加约束前清洗存量违规行，否则 SQLite 重建表时整条迁移失败（PERF-10）。

    - 能修的就地修：score 钳到 [0, 100]，cycles < 1 记 1，非法 severity 记 low，
      非法 status 记 watching（watching 不参与回看，不会污染命中率）；
    - 修不了的删除：对象类型/方向非法、代码格式不符。这些行无法对应到任何
      对象，详情页本来就重建不出序列。
    正常写入路径产生不了违规行，预期两类计数都是 0；非 0 时打印到迁移输出。
    """
    DetectorSignal = apps.get_model('stocks', 'DetectorSignal')
    fixed = deleted = 0
    bad_ids = []
    rows = DetectorSignal.objects.only(
        'id', 'target_kind', 'target_code', 'direction', 'severity', 'status', 'score', 'cycles',
    )
    for sig in rows.iterator(chunk_size=2000):
        if (sig.target_kind not in _KINDS or sig.direction not in _DIRECTIONS
                or not _code_ok(sig.target_kind, sig.target_code)):
            bad_ids.append(sig.id)
            continue
        changes = {}
        if sig.score is None or sig.score < 0:
            changes['score'] = 0.0
        elif sig.score > 100:
            changes['score'] = 100.0
        if sig.cycles is None or sig.cycles < 1:
            changes['cycles'] = 1
        if sig.severity not in _SEVERITIES:
            changes['severity'] = 'low'
        if sig.status not in _STATUSES:
            changes['status'] = 'watching'
        if changes:
            DetectorSignal.objects.filter(pk=sig.pk).update(**changes)
            fixed += 1
    for i in range(0, len(bad_ids), 500):
        n, _ = DetectorSignal.objects.filter(pk__in=bad_ids[i:i + 500]).delete()
        deleted += n
    if fixed or deleted:
        sys.stdout.write(f'\n  DetectorSignal 约束前清洗：修正 {fixed} 行，删除 {deleted} 行\n')


